import { TransactionRecord } from "../types";

/**
 * MockContractService
 *
 * Implements the intended contract interface in a local sandbox environment:
 * - getBalance()      — read mock vault total balance
 * - deposit()         — simulate ETH deposit into vault
 * - withdraw(amount)  — simulate ETH withdrawal from vault
 * - balanceOf(user)   — read user's deposited balance
 *
 * NOTE: All transactions generated by this service are clearly flagged with `isMock: true`.
 * This allows safe local interactive testing without needing testnet ETH, while strictly
 * preserving honest UI disclosure.
 */
export class MockContractService {
  private static STORAGE_KEY = "web3_mock_vault_state";

  private static getState(): {
    totalBalance: number;
    userDeposits: Record<string, number>;
  } {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch {
      // fallback
    }
    // Default initial mock vault balance: 4.50 ETH
    return {
      totalBalance: 4.5,
      userDeposits: {},
    };
  }

  private static saveState(state: { totalBalance: number; userDeposits: Record<string, number> }): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(state));
    } catch {
      // ignore
    }
  }

  public static async getBalance(): Promise<string> {
    // Small network delay simulation
    await new Promise((r) => setTimeout(r, 200));
    const state = this.getState();
    return state.totalBalance.toFixed(4);
  }

  public static async getUserVaultBalance(userAddress: string): Promise<string> {
    await new Promise((r) => setTimeout(r, 200));
    if (!userAddress) return "0.0000";
    const state = this.getState();
    const balance = state.userDeposits[userAddress.toLowerCase()] || 0;
    return balance.toFixed(4);
  }

  public static async deposit(
    userAddress: string,
    amountEth: string
  ): Promise<{ txHash: string; record: TransactionRecord }> {
    const num = parseFloat(amountEth);
    if (isNaN(num) || num <= 0) {
      throw new Error("Deposit amount must be greater than zero.");
    }

    // Simulate mining delay (1.8 seconds)
    await new Promise((r) => setTimeout(r, 1800));

    const state = this.getState();
    const userKey = userAddress.toLowerCase();
    state.totalBalance += num;
    state.userDeposits[userKey] = (state.userDeposits[userKey] || 0) + num;
    this.saveState(state);

    const txHash = this.generateMockTxHash();
    const record: TransactionRecord = {
      id: txHash,
      hash: txHash,
      type: "deposit",
      amount: num.toFixed(4),
      timestamp: Date.now(),
      status: "confirmed",
      blockNumber: Math.floor(5890000 + Math.random() * 1000),
      isMock: true,
    };

    return { txHash, record };
  }

  public static async withdraw(
    userAddress: string,
    amountEth: string
  ): Promise<{ txHash: string; record: TransactionRecord }> {
    const num = parseFloat(amountEth);
    if (isNaN(num) || num <= 0) {
      throw new Error("Withdrawal amount must be greater than zero.");
    }

    const state = this.getState();
    const userKey = userAddress.toLowerCase();
    const currentDeposit = state.userDeposits[userKey] || 0;

    if (num > currentDeposit) {
      throw new Error(
        `Insufficient deposited balance. You have deposited ${currentDeposit.toFixed(
          4
        )} ETH in this vault, but tried to withdraw ${num.toFixed(4)} ETH.`
      );
    }

    if (num > state.totalBalance) {
      throw new Error("Vault contract has insufficient liquid funds.");
    }

    // Simulate mining delay (1.8 seconds)
    await new Promise((r) => setTimeout(r, 1800));

    state.totalBalance -= num;
    state.userDeposits[userKey] = currentDeposit - num;
    this.saveState(state);

    const txHash = this.generateMockTxHash();
    const record: TransactionRecord = {
      id: txHash,
      hash: txHash,
      type: "withdraw",
      amount: num.toFixed(4),
      timestamp: Date.now(),
      status: "confirmed",
      blockNumber: Math.floor(5890000 + Math.random() * 1000),
      isMock: true,
    };

    return { txHash, record };
  }

  public static resetVault(): void {
    try {
      localStorage.removeItem(this.STORAGE_KEY);
    } catch {
      // ignore
    }
  }

  private static generateMockTxHash(): string {
    const chars = "0123456789abcdef";
    let hash = "0x";
    for (let i = 0; i < 64; i++) {
      hash += chars[Math.floor(Math.random() * chars.length)];
    }
    return hash;
  }
}
